import {cabinet,rect,text,tile} from './cabinet.js';
export const slideSolved=b=>b.every((v,i)=>v===(i+1)%9);
export function slideMove(board,i){const z=board.indexOf(0);if(i<0||i>8||Math.abs(i%3-z%3)+Math.abs(Math.floor(i/3)-Math.floor(z/3))!==1)return false;[board[i],board[z]]=[board[z],board[i]];return true;}
export function scrambleSlide(random=Math.random){const b=[1,2,3,4,5,6,7,8,0];let prev=-1;for(let n=0;n<100;n++){const z=b.indexOf(0),opts=[z-3,z+3,z-1,z+1].filter(i=>i!==prev&&i>=0&&i<9&&Math.abs(i%3-z%3)+Math.abs(Math.floor(i/3)-Math.floor(z/3))===1);slideMove(b,opts[Math.floor(random()*opts.length)]);prev=z;}if(slideSolved(b))slideMove(b,7);return b;}
export function createSlide(mount,api){const q=cabinet(mount,api,{accent:'#ffbe80',height:440}),c=q.c;let board=scrambleSlide(),flash=-1,t=0;
 function move(i){if(!q.active)return;if(!slideMove(board,i)){q.sound('blocked');return;}flash=board.indexOf(0);t=.16;q.add(1);q.sound('slide');if(slideSolved(board))q.finish('Everything in place.',`${q.score} moves · ${Math.ceil(q.elapsed)} seconds. Beautifully sorted.`,true);}
 return {start(){board=scrambleSlide();t=0;q.start();},tap(p){p=q.local(p);const x=Math.floor((p.x-18)/108),y=Math.floor((p.y-58)/108);if(x>=0&&x<3&&y>=0&&y<3)move(y*3+x);},direction(d){const z=board.indexOf(0),i=z+({left:1,right:-1,up:3,down:-3}[d]||0);move(i);},action(){q.say('Tap a tile beside the empty space');},tick(dt){q.frame(dt,dt=>{t-=dt;},()=>{q.header('SLIDE INTO ORDER',`${Math.floor(q.elapsed)}s`);rect(c,12,52,336,336,'#332c2a',16);board.forEach((v,i)=>{const x=18+i%3*108,y=58+Math.floor(i/3)*108;if(v)tile(c,x+3,y+3,96,96,v===i+1?'#ffcf92':'#92705c',v);else{rect(c,x+3,y+3,96,96,'#171f29',10);if(t>0&&flash===i)text(c,'·',x+51,y+51,30,'#ffcf92');}});q.footer('Arrange 1–8. Leave the last space empty.');});},destroy:q.destroy};}
